"""Patch the Android project generated by `flutter create` for notifications
and the background scanner service. Run from the repo root."""
import pathlib
import re
import sys

manifest_path = pathlib.Path("android/app/src/main/AndroidManifest.xml")
manifest = manifest_path.read_text(encoding="utf-8")

# --- permissions -----------------------------------------------------------
permissions = [
    "android.permission.INTERNET",
    "android.permission.POST_NOTIFICATIONS",
    "android.permission.FOREGROUND_SERVICE",
    "android.permission.FOREGROUND_SERVICE_DATA_SYNC",
    "android.permission.WAKE_LOCK",
]
perm_xml = "".join(
    f'    <uses-permission android:name="{p}"/>\n'
    for p in permissions
    if f'android:name="{p}"' not in manifest
)

# --- tools namespace on <manifest> ----------------------------------------
if "xmlns:tools=" not in manifest:
    manifest = manifest.replace(
        "<manifest ",
        '<manifest xmlns:tools="http://schemas.android.com/tools" ',
        1,
    )

# --- foreground service declaration (Android 14 needs the type) -----------
service_xml = (
    '        <service\n'
    '            android:name="id.flutter.flutter_background_service.BackgroundService"\n'
    '            android:exported="true"\n'
    '            android:foregroundServiceType="dataSync"\n'
    '            tools:replace="android:exported,android:foregroundServiceType"/>\n'
)

manifest = manifest.replace("<application", perm_xml + "    <application", 1)
manifest = manifest.replace("</application>", service_xml + "    </application>", 1)
manifest_path.write_text(manifest, encoding="utf-8")

# --- core library desugaring (needed by flutter_local_notifications) --------
kts = pathlib.Path("android/app/build.gradle.kts")
groovy = pathlib.Path("android/app/build.gradle")
if kts.exists():
    text = kts.read_text(encoding="utf-8")
    text = re.sub(
        r"compileOptions\s*\{",
        "compileOptions {\n        isCoreLibraryDesugaringEnabled = true",
        text,
        count=1,
    )
    text += '\ndependencies {\n    coreLibraryDesugaring("com.android.tools:desugar_jdk_libs:2.1.4")\n}\n'
    kts.write_text(text, encoding="utf-8")
elif groovy.exists():
    text = groovy.read_text(encoding="utf-8")
    text = re.sub(
        r"compileOptions\s*\{",
        "compileOptions {\n        coreLibraryDesugaringEnabled true",
        text,
        count=1,
    )
    text += "\ndependencies {\n    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.4'\n}\n"
    groovy.write_text(text, encoding="utf-8")
else:
    sys.exit("No android/app/build.gradle(.kts) found")

print("Android project patched")
